(function () {
  'use strict';
  class DataDetectiveAdapter extends USF.SimulationAdapter {
    constructor() {
      super();
      this.name = 'DataDetective: SQL Query Crime Scenes';
      this.version = '1.1.0';
      this._lastRenderedPeriod = 0;
      // Value -> i18n option-key maps (strategy keys are NOT simply 'opt_'+value).
      this.STRAT_KEY = {
        trend_analysis: 'opt_trend', segmentation: 'opt_segmentation', correlation: 'opt_correlation',
        performance: 'opt_performance', behavioral: 'opt_behavioral', anomaly: 'opt_anomaly'
      };
      this.DIM_KEY = {
        time: 'opt_time', product: 'opt_product', customer: 'opt_customer',
        geography: 'opt_geography', channel: 'opt_channel', transaction: 'opt_transaction'
      };
      this.TECH_KEY = {
        group_filter: 'opt_group_filter', join_having: 'opt_join_having', multijoin_subquery: 'opt_multijoin_subquery',
        window_cte: 'opt_window_cte', selfjoin_lag: 'opt_selfjoin_lag', complex_subquery: 'opt_complex_subquery'
      };
      this.CASES = [
        { titleKey:'case1_title', briefKey:'case1_brief', schemaKey:'case1_schema', difficulty:'Fundamentals', difficultyKey:'diff_fundamentals', correctStrategy:'trend_analysis', correctDimension:'product', correctTechnique:'group_filter', feedbackCorrectKey:'case1_feedback_correct', feedbackPartialKey:'case1_feedback_partial', feedbackWrongKey:'case1_feedback_wrong' },
        { titleKey:'case2_title', briefKey:'case2_brief', schemaKey:'case2_schema', difficulty:'Fundamentals', difficultyKey:'diff_fundamentals', correctStrategy:'segmentation', correctDimension:'customer', correctTechnique:'join_having', feedbackCorrectKey:'case2_feedback_correct', feedbackPartialKey:'case2_feedback_partial', feedbackWrongKey:'case2_feedback_wrong' },
        { titleKey:'case3_title', briefKey:'case3_brief', schemaKey:'case3_schema', difficulty:'Intermediate', difficultyKey:'diff_intermediate', correctStrategy:'correlation', correctDimension:'product', correctTechnique:'multijoin_subquery', feedbackCorrectKey:'case3_feedback_correct', feedbackPartialKey:'case3_feedback_partial', feedbackWrongKey:'case3_feedback_wrong' },
        { titleKey:'case4_title', briefKey:'case4_brief', schemaKey:'case4_schema', difficulty:'Intermediate', difficultyKey:'diff_intermediate', correctStrategy:'performance', correctDimension:'channel', correctTechnique:'window_cte', feedbackCorrectKey:'case4_feedback_correct', feedbackPartialKey:'case4_feedback_partial', feedbackWrongKey:'case4_feedback_wrong' },
        { titleKey:'case5_title', briefKey:'case5_brief', schemaKey:'case5_schema', difficulty:'Advanced', difficultyKey:'diff_advanced', correctStrategy:'behavioral', correctDimension:'customer', correctTechnique:'selfjoin_lag', feedbackCorrectKey:'case5_feedback_correct', feedbackPartialKey:'case5_feedback_partial', feedbackWrongKey:'case5_feedback_wrong' },
        { titleKey:'case6_title', briefKey:'case6_brief', schemaKey:'case6_schema', difficulty:'Advanced', difficultyKey:'diff_advanced', correctStrategy:'anomaly', correctDimension:'transaction', correctTechnique:'complex_subquery', feedbackCorrectKey:'case6_feedback_correct', feedbackPartialKey:'case6_feedback_partial', feedbackWrongKey:'case6_feedback_wrong' }
      ];
    }

    _t(key, params) {
      return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(key, params) : key;
    }
    _optLabel(type, v) {
      var map = type === 'strategy' ? this.STRAT_KEY : (type === 'dimension' ? this.DIM_KEY : this.TECH_KEY);
      var k = map[v] || v;
      return this._t(k);
    }

    initialize(state) {
      if (!state.domainState || Object.keys(state.domainState).length === 0) {
        state.domainState = { score: 0, casesSolved: 0, totalCorrectChoices: 0, totalChoicesMade: 0, scoreHistory: [], accuracyHistory: [] };
      }
      if (!state.decisions || Object.keys(state.decisions).length === 0) {
        state.decisions = { strategy: 'trend_analysis', dimension: 'time', technique: 'group_filter' };
      }
      this._updateBriefing(state);
    }

    validateDecisions(decisions) {
      // Capture inputs and validate ONLY. No UI mutation here (that caused a
      // mid-submit briefing flip/flicker and reset).
      var strategyEl = document.getElementById('strategySelect');
      var dimensionEl = document.getElementById('dimensionSelect');
      var techniqueEl = document.getElementById('techniqueSelect');
      if (strategyEl) decisions.strategy = strategyEl.value;
      if (dimensionEl) decisions.dimension = dimensionEl.value;
      if (techniqueEl) decisions.technique = techniqueEl.value;
      if (!decisions.strategy || !decisions.dimension || !decisions.technique) {
        window.mySimulation.uiManager.showNotification(window.mySimulation.t('validation_warning'), 'warning');
        return false;
      }
      return true;
    }

    calculateResults(state) {
      var d = state.decisions;
      var caseIdx = Math.min((state.currentPeriod || 1) - 1, this.CASES.length - 1);
      var currentCase = this.CASES[caseIdx];
      var correctCount = 0;
      if (d.strategy === currentCase.correctStrategy) correctCount++;
      if (d.dimension === currentCase.correctDimension) correctCount++;
      if (d.technique === currentCase.correctTechnique) correctCount++;
      var pointsMap = { 0: 10, 1: 30, 2: 60, 3: 100 };
      var points = pointsMap[correctCount];
      var solved = correctCount === 3;
      state.domainState.score += points;
      if (solved) state.domainState.casesSolved += 1;
      state.domainState.totalCorrectChoices += correctCount;
      state.domainState.totalChoicesMade += 3;
      state.domainState.scoreHistory.push(points);
      var accPct = Math.round((state.domainState.totalCorrectChoices / state.domainState.totalChoicesMade) * 100);
      state.domainState.accuracyHistory.push(accPct);

      var feedbackKey = currentCase.feedbackWrongKey;
      if (correctCount === 3) feedbackKey = currentCase.feedbackCorrectKey;
      else if (correctCount >= 2) feedbackKey = currentCase.feedbackPartialKey;

      var feedbackPanel = document.getElementById('feedbackPanel');
      var feedbackText = document.getElementById('feedbackText');
      if (feedbackPanel && feedbackText) {
        feedbackPanel.style.display = 'block';
        var html = '<strong>' + points + '/100</strong> — ' + window.mySimulation.t(feedbackKey);
        if (correctCount < 3) {
          // Pedagogical reveal: show the correct approach for this case.
          html += '<div class="datadetective-sim-correct-answer"><span class="datadetective-sim-ca-label">'
            + window.mySimulation.t('correct_answer_label') + '</span> '
            + this._optLabel('strategy', currentCase.correctStrategy) + ' · '
            + this._optLabel('dimension', currentCase.correctDimension) + ' · '
            + this._optLabel('technique', currentCase.correctTechnique) + '</div>';
        }
        feedbackText.innerHTML = html;
      }

      // The framework increments state.currentPeriod AFTER calculateResults
      // returns. Render the next case from the LIVE (already-advanced) period —
      // NEVER +1 (that double-advanced and skipped a whole case). Feedback is
      // intentionally left visible so the player can read their result.
      var self = this;
      setTimeout(function () {
        var live = (window.mySimulation && window.mySimulation.state) ? window.mySimulation.state : state;
        self._updateBriefing(live);
      }, 450);

      return {
        period: state.currentPeriod, points: points, correctCount: correctCount, solved: solved,
        cumulativeScore: state.domainState.score, casesSolved: state.domainState.casesSolved, accuracy: accPct
      };
    }

    setupUI(uiManager) {
      var self = this;
      // Clamp the case counter defensively (never show "7 of 6").
      uiManager.bind('currentDay', 'currentPeriod', function (v) { return Math.min(v, self.CASES.length); });
      uiManager.bind('maxPeriods', 'maxPeriods');
      uiManager.bind('scoreDisplay', 'domainState.score', function (v) { return v.toLocaleString(); });
      uiManager.bind('casesSolvedDisplay', 'domainState.casesSolved', function (v) { return v + '/' + self.CASES.length; });
      uiManager.bind('accuracyDisplay', 'domainState.totalChoicesMade', function (v) {
        return v > 0 ? Math.round((window.mySimulation.state.domainState.totalCorrectChoices / v) * 100) + '%' : '0%';
      });
      // Undo is framework-owned; it rolls back score/period but does NOT re-render
      // this sim's briefing. Re-render from the restored period on the next tick
      // (after the framework's synchronous undo handler runs) and hide feedback.
      var undoBtn = document.getElementById('undoBtn');
      if (undoBtn && !undoBtn._ddUndoBound) {
        undoBtn._ddUndoBound = true;
        undoBtn.addEventListener('click', function () {
          setTimeout(function () {
            var live = window.mySimulation ? window.mySimulation.state : null;
            if (live) self._updateBriefing(live);
            var fp = document.getElementById('feedbackPanel');
            if (fp) fp.style.display = 'none';
          }, 0);
        });
      }
    }

    getChartConfig() {
      return {
        scoreChart: {
          type: 'bar',
          data: { labels: [], datasets: [{ label: this._t('chart_points_label'), data: [], backgroundColor: 'rgba(240,192,64,0.7)', borderColor: '#f0c040', borderWidth: 2, borderRadius: 6 }] },
          options: {
            responsive: true, maintainAspectRatio: false,
            plugins: { title: { display: true, text: this._t('chart_title'), color: '#f0c040' }, legend: { labels: { color: '#a0c0d0' } } },
            scales: {
              y: { beginAtZero: true, max: 110, ticks: { color: '#80b0c0' }, grid: { color: 'rgba(42,74,90,0.5)' } },
              x: { ticks: { color: '#80b0c0' }, grid: { color: 'rgba(42,74,90,0.3)' } }
            }
          }
        }
      };
    }

    getChartData(state) {
      var self = this;
      var labels = state.domainState.scoreHistory.map(function (_, i) { return self._t('period_label') + ' ' + (i + 1); });
      return { scoreChart: { labels: labels, datasets: [{ data: state.domainState.scoreHistory }] } };
    }

    getPerformanceSummary(history) {
      if (!history.length) return {};
      var totalPoints = history.reduce(function (s, r) { return s + (r.results ? r.results.points : 0); }, 0);
      var totalSolved = history.reduce(function (s, r) { return s + (r.results && r.results.solved ? 1 : 0); }, 0);
      var totalCorrect = history.reduce(function (s, r) { return s + (r.results ? r.results.correctCount : 0); }, 0);
      var totalChoices = history.length * 3;
      var accuracy = Math.round((totalCorrect / totalChoices) * 100);
      // Thresholds unchanged; only the labels/insights are now localized.
      var perfKey = 'perf_junior';
      if (totalPoints >= 400 && accuracy >= 60) perfKey = 'perf_senior';
      if (totalPoints >= 500 && accuracy >= 75) perfKey = 'perf_lead';
      if (totalPoints >= 560 && accuracy >= 85) perfKey = 'perf_chief';
      var insightKey = totalPoints >= 500 ? 'insight_high' : (totalPoints >= 300 ? 'insight_mid' : 'insight_low');
      return {
        totalPoints: totalPoints,
        casesSolved: totalSolved,
        accuracy: accuracy + '%',
        performance: this._t(perfKey),
        insights: [this._t(insightKey)]
      };
    }

    getHint(state, results) {
      if (!results) return null;
      if (results.correctCount === 0) return window.mySimulation.t('hint_wrong');
      if (results.correctCount === 1) return window.mySimulation.t('hint_partial_low');
      if (results.correctCount === 2) return window.mySimulation.t('hint_partial_high');
      return window.mySimulation.t('hint_perfect');
    }

    getHistoryTableConfig() {
      var self = this;
      return [
        { key: 'results.period', label: 'Case', i18nKey: 'col_case' },
        { key: 'decisions.strategy', label: 'Strategy', i18nKey: 'col_strategy', formatter: function (v) { return self._optLabel('strategy', v); } },
        { key: 'decisions.dimension', label: 'Dimension', i18nKey: 'col_dimension', formatter: function (v) { return self._optLabel('dimension', v); } },
        { key: 'decisions.technique', label: 'SQL Technique', i18nKey: 'col_technique', formatter: function (v) { return self._optLabel('technique', v); } },
        { key: 'results.correctCount', label: 'Correct', i18nKey: 'col_correct', formatter: function (v) { return v + '/3'; } },
        { key: 'results.points', label: 'Points', i18nKey: 'col_points' },
        { key: 'results.solved', label: 'Solved', i18nKey: 'col_solved', formatter: function (v) { return v ? '✅' : '❌'; } }
      ];
    }

    getPresets() { return null; }

    _updateBriefing(state) {
      var period = (state && state.currentPeriod) ? state.currentPeriod : 1;
      var idx = Math.min(period - 1, this.CASES.length - 1);
      idx = Math.max(0, idx);
      this._lastRenderedPeriod = period;
      var currentCase = this.CASES[idx];
      var briefEl = document.getElementById('briefingText');
      if (briefEl) briefEl.innerHTML = this._t(currentCase.briefKey);
      var schemaEl = document.getElementById('schemaHintText');
      if (schemaEl) schemaEl.innerHTML = this._t(currentCase.schemaKey);
      var diffEl = document.getElementById('difficultyDisplay');
      if (diffEl) diffEl.textContent = this._t(currentCase.difficultyKey);
      // NOTE: does not hide the feedback panel — feedback persists until the next
      // grading so the player can actually read their result.
    }

    getTranslations() {
      return {
        en: {
          title: `DataDetective: SQL Query Crime Scenes`,
          subtitle: `Solve business mysteries with the right analytical approach`,
          period_label: `Case`,
          period_of: `of`,
          score_label: `Investigation Score`,
          cases_solved_label: `Cases Solved`,
          accuracy_label: `Accuracy`,
          difficulty_label: `Difficulty`,
          briefing_heading: `Mystery Brief`,
          schema_hint_label: `Relevant Tables:`,
          decisions_heading: `Your Investigation Plan`,
          strategy_label: `Analysis Strategy`,
          dimension_label: `Primary Dimension`,
          technique_label: `SQL Technique`,
          submit_btn: `Submit Investigation`,
          undo_btn: `Undo Last Case`,
          history_heading: `Case Log`,
          feedback_heading: `Investigation Results`,
          validation_warning: `Please select all three investigation parameters before submitting.`,
          correct_answer_label: `Correct approach:`,
          diff_fundamentals: `Fundamentals`,
          diff_intermediate: `Intermediate`,
          diff_advanced: `Advanced`,
          completion_title: `Investigation Closed`,
          perf_junior: `Junior Analyst`,
          perf_senior: `Senior Analyst`,
          perf_lead: `Lead Detective`,
          perf_chief: `Chief Data Officer`,
          insight_high: `Excellent analytical instincts — strong match between business questions and SQL techniques.`,
          insight_mid: `Good foundation — practice matching advanced SQL techniques to complex business scenarios.`,
          insight_low: `Review SQL fundamentals: focus on when to use JOINs, GROUP BY, and subqueries for different question types.`,
          chart_title: `Investigation Performance`,
          chart_points_label: `Points per Case`,
          opt_trend: `Trend Analysis`,
          opt_segmentation: `Customer Segmentation`,
          opt_correlation: `Correlation Analysis`,
          opt_performance: `Performance Comparison`,
          opt_behavioral: `Behavioral Pattern Analysis`,
          opt_anomaly: `Anomaly Detection`,
          opt_time: `Time Period`,
          opt_product: `Product / Category`,
          opt_customer: `Customer Segment`,
          opt_geography: `Geographic Region`,
          opt_channel: `Marketing Channel`,
          opt_transaction: `Transaction Details`,
          opt_group_filter: `GROUP BY + WHERE Filtering`,
          opt_join_having: `JOIN + HAVING Clauses`,
          opt_multijoin_subquery: `Multi-table JOIN + Subqueries`,
          opt_window_cte: `Window Functions + CTEs`,
          opt_selfjoin_lag: `Self-JOIN + LAG/LEAD`,
          opt_complex_subquery: `Complex Subqueries + CASE`,
          case1_title: `The Revenue Drop`,
          case1_brief: `<strong>CASE FILE #1 — The Revenue Drop</strong><br><br>The CFO has flagged an 18% revenue decline in Q3 compared to Q2. The board wants answers by Friday.<br><br>Your mission: identify the root cause. Was it seasonal? A product issue? A pricing error? Start with total revenue by period, then drill down by product category to isolate the source. The answer lies in the data — you need to slice it correctly.`,
          case1_schema: `<strong>orders</strong>, <strong>order_items</strong>, <strong>products</strong>, <strong>categories</strong>`,
          case1_feedback_correct: `Brilliant detective work! Trend Analysis on the Product dimension using GROUP BY + WHERE filtering is exactly how a senior analyst would approach this. You correctly identified that drilling down by product category with date filtering reveals the electronics category dropped 40% — a discontinued laptop model was the root cause.`,
          case1_feedback_partial: `Good instincts, but your approach was not fully optimized. The key was to use Trend Analysis on Products with GROUP BY + date filtering to drill from total revenue down to the specific product category causing the decline.`,
          case1_feedback_wrong: `The revenue drop case requires Trend Analysis as the strategy — you need to compare periods over time. The primary dimension should be Product/Category since the cause was a discontinued product line. GROUP BY with WHERE filtering is the right SQL technique for time-based aggregation and drilling.`,
          case2_title: `The Shifting Segment`,
          case2_brief: `<strong>CASE FILE #2 — The Shifting Segment</strong><br><br>Marketing reports that the top customer segment has changed. The loyal B2B buyers who drove 60% of revenue last year now account for only 35%.<br><br>Your mission: identify who the new top segment is, what they buy, and how much they spend. You need to group customers, filter by meaningful thresholds, and compare segments across periods.`,
          case2_schema: `<strong>customers</strong>, <strong>orders</strong>, <strong>order_items</strong>, <strong>products</strong>`,
          case2_feedback_correct: `Perfect analysis! Customer Segmentation using JOINs with HAVING clauses is the textbook approach. By joining customers to their orders and filtering with HAVING on aggregate spend, you identified the emerging D2C segment driving the shift.`,
          case2_feedback_partial: `Close! The key insight is that this is a segmentation problem focused on Customer dimension. JOIN + HAVING lets you combine customer data with order totals and filter for meaningful segments based on aggregate thresholds.`,
          case2_feedback_wrong: `This mystery is about identifying customer segments — that requires Customer Segmentation as the strategy, focused on the Customer dimension. JOIN + HAVING is essential because you need to combine customer and order tables, then filter groups by aggregate conditions (e.g., total spend > threshold).`,
          case3_title: `The Support Spike`,
          case3_brief: `<strong>CASE FILE #3 — The Support Spike</strong><br><br>Support tickets tripled in the two weeks following a major product launch. Customer satisfaction scores are plummeting and the VP of Product wants to know which specific products are generating complaints.<br><br>Your mission: correlate support tickets with product purchases. Which products launched recently AND generated the most tickets? You need to connect data across multiple tables to find the overlap.`,
          case3_schema: `<strong>support_tickets</strong>, <strong>products</strong>, <strong>orders</strong>, <strong>order_items</strong>, <strong>categories</strong>`,
          case3_feedback_correct: `Outstanding! Correlation Analysis on the Product dimension using Multi-table JOINs with Subqueries is exactly right. You connected support tickets to specific products through orders, and used subqueries to filter for recently launched items — revealing 3 products responsible for 80% of the spike.`,
          case3_feedback_partial: `You were on the right track. This case requires Correlation Analysis — linking two phenomena (support tickets and product launches). The Product dimension is central, and Multi-table JOINs with Subqueries are needed to traverse from tickets through orders to products.`,
          case3_feedback_wrong: `The support spike requires Correlation Analysis — you are linking cause (product launch) to effect (support tickets). Focus on the Product dimension and use Multi-table JOINs + Subqueries to connect support_tickets to products through the orders and order_items tables.`,
